import os
import google.cloud.documentai_v1 as documentai

def extract_receipt_fields(payload, config=None):
    config = config or {}
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
    location = "us"  # Or your preferred location
    processor_id = os.environ.get("DOCUMENTAI_PROCESSOR_ID_RECEIPT") # e.g., "YOUR_PROCESSOR_ID" for a specialized receipt parser

    documentai_client = documentai.DocumentProcessorServiceClient()

    name = documentai_client.processor_path(project_id, location, processor_id)

    raw_document = documentai.RawDocument(
        content=payload,
        mime_type="application/pdf" # Assuming PDF, adjust if it's an image like "image/jpeg"
    )

    request = documentai.ProcessRequest(
        name=name,
        raw_document=raw_document
    )

    response = documentai_client.process_document(request=request)

    document = response.document

    # Initialize fields
    merchant_name = None
    total_amount = None
    tax_amount = None
    items = []

    # Helper to get text from a text anchor
    def get_text_from_anchor(text_anchor):
        if not text_anchor.text_segments:
            return None
        start_index = text_anchor.text_segments[0].start_index
        end_index = text_anchor.text_segments[0].end_index
        return document.text[start_index:end_index]

    # Parse entities
    for entity in document.entities:
        if entity.type_ == "merchant_name" and entity.mention_text:
            merchant_name = entity.mention_text
        elif entity.type_ == "total_amount" and entity.mention_text:
            total_amount = float(entity.mention_text.replace('$', '').replace(',', ''))
        elif entity.type_ == "tax_amount" and entity.mention_text:
            tax_amount = float(entity.mention_text.replace('$', '').replace(',', ''))
        elif entity.type_ == "line_item":
            item_description = None
            item_amount = None
            for prop in entity.properties:
                if prop.type_ == "line_item/description" and prop.mention_text:
                    item_description = prop.mention_text
                elif prop.type_ == "line_item/amount" and prop.mention_text:
                    item_amount = float(prop.mention_text.replace('$', '').replace(',', ''))
            if item_description or item_amount:
                items.append({"description": item_description, "amount": item_amount})

    result = {
        "merchant": merchant_name,
        "total": total_amount,
        "tax": tax_amount,
        "items": items
    }
    return result
